// api.js
export async function getJSON(url, signal) {
  const res = await fetch(url, { signal });
  if (!res.ok) throw new Error(`HTTP ${res.status} for ${url}`);
  return res.json();
}

// dashboard.js
import { getJSON } from './api.js';

export default async function loadDashboard(userId, signal) {
  try {
    const [profile, orders] = await Promise.all([
      getJSON(`/api/users/${userId}`, signal),
      getJSON(`/api/users/${userId}/orders`, signal)
    ]);
    return { profile, orders };
  } catch (err) {
    if (err.name === 'AbortError') return null; // component unmounted
    throw err;
  }
}

