const lines = stdin.trim().split('\n');
let i = 0;
const n = parseInt(lines[i++], 10);
const tasks = [];
for (let k = 0; k < n; k++) {
  const [name, d, s] = lines[i++].trim().split(/\s+/);
  tasks.push({ name, t: Number(d), ok: s === 'ok', order: k });
}
const byTime = tasks.slice().sort((a, b) => a.t - b.t || a.order - b.order);
const maxT = Math.max(...tasks.map(t => t.t));
const q = parseInt(lines[i++], 10);
const out = [];
for (let k = 0; k < q; k++) {
  const c = lines[i++].trim();
  let r;
  if (c === 'all') {
    const f = byTime.find(t => !t.ok);
    r = f ? `rejected at ${f.t}: ${f.name}` : `fulfilled at ${maxT}: [${tasks.map(t => t.name).join(', ')}]`;
  } else if (c === 'allSettled') {
    r = `settled at ${maxT}: ` + tasks.map(t => t.name + '=' + (t.ok ? 'fulfilled' : 'rejected')).join(', ');
  } else if (c === 'race') {
    const f = byTime[0];
    r = `${f.ok ? 'fulfilled' : 'rejected'} at ${f.t}: ${f.name}`;
  } else {
    const f = byTime.find(t => t.ok);
    r = f ? `fulfilled at ${f.t}: ${f.name}` : `rejected at ${maxT}: AggregateError`;
  }
  out.push(c + ': ' + r);
}
console.log(out.join('\n'));

